INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (223, 'REF-01031', NULL, 11, 'MOB', NULL, NULL, NULL, 'KR', 'street trees along an access route', 'numerical', '2.1', 'm', '가로수는 지면에서 2.1미터까지 가지치기를 하여야 한다.', 'Enforcement Rule (Korea), Annex 1, item 1(마)(2)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '1', NULL, '마', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'law.go.kr Annex 1 download, PDF page 1 of 22', 'skim', 'preliminary', NULL, 'Quantity: height above the ground to which street-tree branches are to be pruned, which sets the clear height over the route. A pruning height, not a headroom clause for a built element. Lens MOB: item 1 is headed 장애인등의 통행이 가능한 접근로 (access route usable by persons with disabilities) [ASSUMPTION: lens is the reader''s filing].', '2026-11-06 04:56', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:56', 'session_2026-11-06-pipeline-batch-2', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (224, 'REF-01031', NULL, 9, 'MOB', NULL, NULL, NULL, 'KR', 'door of the water-closet stall in an accessible toilet', 'numerical', '0.9', 'm', '(다) 출입문의 통과유효폭은 0.9미터 이상으로 하여야 한다.', 'Enforcement Rule (Korea), Annex 1, item 13(나)(1)(다)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '13', NULL, '나', '다', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'law.go.kr Annex 1 download, PDF page 11 of 22', 'skim', 'preliminary', NULL, 'Quantity: minimum clear passage width of the stall door in an accessible toilet. A separate clause from item 6 (entrance doors, row 207), same figure. Lens MOB: item 13 is headed 장애인등의 이용이 가능한 화장실 (toilets usable by persons with disabilities) [ASSUMPTION: lens is the reader''s filing].', '2026-11-06 04:56', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:56', 'session_2026-11-06-pipeline-batch-2', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (225, 'REF-01031', NULL, 4, 'MOB', NULL, NULL, NULL, 'KR', 'ramp', 'numerical', '1.2', 'm', '(1) 경사로의 유효폭은 1.2미터 이상으로 하여야 한다.', 'Enforcement Rule (Korea), Annex 1, item 12(가)(1)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '12', NULL, '가', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'law.go.kr Annex 1 download, PDF page 9 of 22', 'skim', 'preliminary', NULL, 'Quantity: minimum clear width of a ramp. The sentence goes on to permit 0.9 m where 1.2 m cannot be obtained in a building extension, rebuilding or change of use; that relaxation is not filed as a row. Lens MOB: item 12 is the ramp item of an annex about persons with disabilities [ASSUMPTION: lens is the reader''s filing].', '2026-11-06 04:56', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:56', 'session_2026-11-06-pipeline-batch-2', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (226, 'REF-01032', NULL, 6, 'MOB', NULL, NULL, NULL, 'PT', 'controls and operable elements (buttons, keys and similar)', 'numerical', '22', 'N', 'Poder ser operados sem ser requerida uma força superior a 22 N;', 'Decreto-Lei 163/2006, Annex, item 4.12.1(4)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '4', NULL, '4.12.1', '4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Diario da Republica 1a serie N.o 152, 8 Aug 2006, PDF page 20 of 20', 'skim', 'preliminary', NULL, 'Quantity: maximum force to operate a control. Sub-paragraph (3) requires a form easy to grip with one hand without firm grasp or wrist rotation. Lens MOB: the decree is the Portuguese accessibility regime for people with reduced mobility [ASSUMPTION: lens is the reader''s filing].', '2026-11-06 04:56', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:56', 'session_2026-11-06-pipeline-batch-2', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (227, 'REF-01032', NULL, 4, 'MOB', NULL, NULL, NULL, 'PT', 'ramp', 'numerical', '1.2', 'm', 'As rampas devem possuir uma largura não inferior a 1,2 m, excepto nas seguintes situações:', 'Decreto-Lei 163/2006, Annex, item 2.5.4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '2', NULL, '2.5.4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Diario da Republica 1a serie N.o 152, 8 Aug 2006, PDF page 10 of 20', 'skim', 'preliminary', NULL, 'Quantity: minimum width of a ramp. The two exceptions (0.9 m for a ramp with a horizontal projection of 5 m or less; 0.9 m where two ramps serve one route) are not filed as rows. Lens MOB: the decree is the Portuguese accessibility regime for people with reduced mobility [ASSUMPTION: lens is the reader''s filing].', '2026-11-06 04:56', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:56', 'session_2026-11-06-pipeline-batch-2', 'claim', '>=');
UPDATE "source_value_extractions" SET "notes" = 'Quantity: diameter that would accommodate every user in the study sample for a 360-degree turn; the report states it against the US standard of 1525 mm, which fewer than half of its manual and powered wheelchair users completed within. A finding about the sample, not a recommended standard. Lens MOB: the report measures wheelchair and scooter users, the population these widths serve [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one]. || 2026-11-06 extraction_method CONFIRMED skim (SETTING CORRECTED by the adversarial pass: the setting says whole sample of 495 users. The sentence''s own sample is the 360-degree task sample: Figure 3-13 (PDF page 66) gives 185 + 139 + 15 = 339 participants for All Device Types. The 495 is the study''s total recruitment, not this task''s n.)', "updated_at" = '2026-11-06 04:56' WHERE "extraction_id" = 193;
UPDATE "source_value_extractions" SET "notes" = 'Quantity: width for a corridor with rooms (거실) on both sides; the text says it MAY be set at 1.5 m or more (할 수 있다), a permission, so the comparator records the stated floor only. The quote starts at a line break inside the sentence in the extracted text. Lens ALL: the clause names no population [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one]. || 2026-11-06 figure_role SET claim -> condition (Adversarial pass: 1.5 m for a corridor with rooms on both sides is stated as a permission (할 수 있다) that qualifies the 1.2 m corridor row (208), as batch 23 filed the annex''s relaxation (row 108). Its claim_text starts mid-sentence at a line break and drops its own condition, which the edge quote now carries.)', "updated_at" = '2026-11-06 04:56', "figure_role" = 'condition' WHERE "extraction_id" = 209;
UPDATE "source_value_extractions" SET "notes" = 'Quantity: side of the square activity space (1.4 m by 1.4 m) in front of the water closet so that a wheelchair can turn; stated for newly built toilets. For competition-wheelchair toilets the text states 1.5 m by 1.5 m; not filed. Lens MOB: the clause says 휠체어가 회전할 수 있도록 (so that a wheelchair can turn) [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one]. || 2026-11-06 extraction_method CONFIRMED skim (LOCATOR CORRECTED by the adversarial pass: source_section and loc_section name Annex 1 item 8(나)(1)(가); item 8 is the stairs item. The quoted sentence sits under item 13 (장애인등의 이용이 가능한 화장실, toilets), 나.(1)(가), PDF page 11 of 22. Figure and quote are right; read the locator as item 13 나(1)(가).)', "updated_at" = '2026-11-06 04:56' WHERE "extraction_id" = 211;
UPDATE "source_value_extractions" SET "notes" = 'Quantity: reduced width permitted for a short segment. A permission (podem existir), so the comparator records the stated floor only. Lens ALL: the clause names no population [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one]. || 2026-11-06 figure_role SET claim -> condition (Adversarial pass: a permission that applies only to a short segment is a qualifier of the 1.2 m headline (row 213), as batch 23 filed the same decree''s 12 percent relaxation (row 111); filed as claim it would enter parameter 4 beside the headline.)', "updated_at" = '2026-11-06 04:56', "figure_role" = 'condition' WHERE "extraction_id" = 214;

-- term_adjudications: 1 insert(s), 0 update(s)
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (90, 97, 'DEFERRED', NULL, 'Corrected rationale. The recorded quote is the first sentence under 4.3.5.1 (90-Degree Turn), where this turning clearance is the 90-degree clearance, applicable to circulation, aisles and ramps; the family description in adjudication 88 belongs to the 4.3.5 heading, which the quote does not contain. As used in the quote the phrase names a width at a 90-degree turn, the same quantity as observation 98. Whether it is a term of its own or an expression of TERM-002 at a turn is the owner''s to define; nothing is minted.', '2026-11-06 04:56', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:56', 'session_2026-11-06-pipeline-batch-2');

